def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find connected components of each non-background color.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append((color, cells))

    # A long straight/near-straight bar is the color donor.
    donor = max(comps, key=lambda q: len(q[1]))
    donor_color, donor_cells = donor
    out = [row[:] for row in grid]

    # Recolor the smallest compact component other than the bar, choosing
    # among small components (the marked object to be changed).
    candidates = []
    for color, cells in comps:
        if cells is donor_cells or color == donor_color or len(cells) > 5:
            continue
        ys = [r for r, c in cells]
        xs = [c for r, c in cells]
        area = (max(ys) - min(ys) + 1) * (max(xs) - min(xs) + 1)
        candidates.append((len(cells), area, cells))
    if candidates:
        cells = min(candidates, key=lambda q: (q[0], q[1]))[2]
        for r, c in cells:
            out[r][c] = donor_color
    return out
